#!/bin/bash
# Writes a tiny synthetic builder/gen (no game code) so CI can test the module toolchain where there is
# no compiler yet (the SteamOS check). It is the output of tools/blockgen for a RAM image of our own:
#   0c000000: mov #1,r0 ; add r0,r1 ; rts ; nop
#   tools/make_test_gen.sh <package dir>
set -e
G="$1/builder/gen"; mkdir -p "$G"
cat > "$G/blk_00.c" <<'X'
/* generated by tools/blockgen - do not edit */
#include "sh4sem.h"
#include "blockrt.h"
void B_0c000000_3a77aeb1(Cpu *c) {
  const u32 seg = c->pc & 0xe0000000u;
  SEM_OP_MOV_IMM_IMM_RN(c, 0xe001, seg | 0x0c000000u);
  SEM_OP_ADD_RM_RN(c, 0x310c, seg | 0x0c000002u);
  { u32 tg = c->pr; c->pc = seg | 0x0c000006u; SEM_OP_NOP(c, 0x0009, seg | 0x0c000006u); c->pc = tg; }
  c->cycles += 4;
}
X
cat > "$G/blk_table.c" <<'X'
/* generated by tools/blockgen - do not edit */
#include "sh4sem.h"
#include "blockrt.h"
void B_0c000000_3a77aeb1(Cpu *c);
const BlkEntry blk_table[] = {
  {0x0c000000u, 0x3a77aeb1u, 8u, B_0c000000_3a77aeb1},
};
const int blk_count = 1;
X
